(()=>{
const topics=['认识 DNA','打开模板','建立起点','合成新链','完成与检查'];
const original=[document.querySelector('.experiment'),document.querySelector('.workspace'),document.querySelector('.below')];
const course=document.createElement('section');course.className='dna-course';course.innerHTML=`<nav class="course-path" aria-label="DNA 复制学习主线">${topics.map((x,i)=>`<button data-chapter="${i}" aria-current="false"><span>0${i+1}</span>${x}</button>`).join('')}</nav><div class="course-context"><span id="courseScale"></span><button id="returnFork">查看整体复制叉</button></div><section id="courseContent" aria-labelledby="courseTitle"></section>`;document.querySelector('.heading').after(course);
const template='TACGATCG',complement={A:'T',T:'A',C:'G',G:'C'};let chapter=0,primer=false,added=[],candidate=null,chemistry=false,layer='bases',finishStep=0;
const titles=['从两条反向平行的链开始','解开双链，暴露模板','先给聚合酶一个起点','亲手延伸一条 DNA','整理片段，得到两份 DNA'];
function button(text,fn,cls=''){let b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b}
function go(i){chapter=i;playing=false;$('play').textContent='播放';document.querySelectorAll('[data-chapter]').forEach((b,j)=>b.setAttribute('aria-current',i===j?'step':'false'));original.forEach(e=>e.hidden=i!==1);$('courseScale').textContent=['结构尺度 · 互补与方向','全局尺度 · 原有模型与酶实验','局部尺度 · 引物提供 3′-OH','化学尺度 · 一次加入一个核苷酸','全局尺度 · 半保留复制'][i];$('returnFork').hidden=i===1;if(i===1){$('courseContent').innerHTML='<h2 id="courseTitle">'+titles[i]+'</h2><p>观察解旋酶如何打开模板。用“放大解旋酶”进入分子机制与真实结构；准备好后，继续建立起点。</p><button id="continuePrimer" class="course-primary">继续：建立起点</button>';$('continuePrimer').onclick=()=>go(2);selectExperiment('normal');setProgress(0);return}render()}
function diagram({intro=false}={}){const n=3+added.length,showPrimer=primer||intro;return `<div class="strand-scroll"><div class="strand-diagram ${intro?'intro-strand':''} ${layer==='backbone'&&intro?'backbone-view':''}"><div class="strand-name">模板 DNA</div><div class="base-row template-row"><strong>3′</strong>${[...template].map((b,i)=>`<span class="base ${!intro&&i===n&&primer?'target-base':''}" data-base="${b}">${b}</span>`).join('')}<strong>5′</strong></div><div class="pair-row"><span></span>${[...template].map((_,i)=>`<span>${intro||i<n&&showPrimer?'⋮':i===n&&candidate?'⋮':''}</span>`).join('')}</div><div class="strand-name">${intro?'互补 DNA':'引物 / 新生链'}</div><div class="base-row new-row"><strong>5′</strong>${[...template].map((b,i)=>{const value=intro?complement[b]:i<3?(primer?['A','U','G'][i]:''):i<n?added[i-3]:i===n&&candidate?candidate:'';return `<span class="base ${(intro&&i<7||!intro&&showPrimer&&i<n-1)?'bonded-base':''} ${!intro&&i<3?'rna-base':''} ${!value?'empty-base':''} ${!intro&&i===n&&candidate?'candidate-base':''}" data-base="${value}">${value||'·'}${!intro&&primer&&i===n-1?'<small>3′-OH</small>':''}</span>`}).join('')}<strong>${intro?'3′':''}</strong></div><div class="strand-direction">${intro?'两条链方向相反 · A–T，G–C':'新链延伸 5′ → 3′ · 聚合酶读取模板 3′ → 5′'}</div></div></div>`}
function render(){const panel=$('courseContent');panel.innerHTML=`<div class="lesson-head"><div><div class="eyebrow">DNA 复制 · ${chapter+1} / 5</div><h2 id="courseTitle">${titles[chapter]}</h2></div><span class="lesson-chip">${chapter===3?added.length+' / 5 个 DNA 核苷酸已加入':'可随时切换章节'}</span></div>`;
 if(chapter===0){panel.innerHTML+=`<div class="lesson-grid"><div class="sequence-surface">${diagram({intro:true})}<div class="course-actions" id="introControls"></div></div><div class="lesson-copy"><h3>先分清两种连接</h3><p>同一条链上的核苷酸通过<strong>共价的糖–磷酸骨架</strong>连接；两条链的互补碱基之间形成氢键。双螺旋的稳定性还与碱基堆积有关。</p><p>上方模板从左到右是 3′→5′，下方互补链是 5′→3′。这是把双螺旋展开后的局部示意。</p><div id="introNext"></div></div></div>`;$('introControls').append(button('看碱基配对',()=>{layer='bases';render()}),button('突出骨架',()=>{layer='backbone';render()}));$('introControls').children[layer==='bases'?0:1].setAttribute('aria-pressed','true');$('introNext').append(button('下一步：打开模板',()=>go(1),'course-primary'));return}
 if(chapter===2||chapter===3){panel.innerHTML+=`<div class="lesson-grid"><div class="sequence-surface">${diagram()}<p class="scroll-hint">小屏幕可左右滑动查看整条链。</p><div class="sequence-legend"><span>粉色：RNA 引物 AUG</span><span>绿色：新加入的 DNA</span><span>虚线：配对；横线：骨架</span></div><div id="synthesisVisual"></div></div><div class="lesson-copy"><div id="synthesisControls"></div><p id="synthesisFeedback" role="status"></p><div id="reactionBox" class="reaction-box"></div><div class="course-actions" id="synthesisActions"></div></div></div>`;renderSynthesis();return}
 renderFinish(panel)
}
function renderSynthesis(){const controls=$('synthesisControls'),actions=$('synthesisActions');if(chapter===2){controls.innerHTML='<h3>DNA 聚合酶需要已有的 3′-OH</h3><p>先用引物酶放置一个短 RNA 引物。RNA 用 U 与模板 A 配对；后续合成 DNA 时使用 T。</p>';controls.append(button(primer?'引物已放置':'放置 RNA 引物',()=>{primer=true;render()},'course-primary'));controls.lastChild.disabled=primer;actions.append(button('尝试直接延伸',()=>{$('synthesisFeedback').textContent=primer?'已有 3′-OH，可以继续选择 DNA 核苷酸。':'还不能延伸：缺少引物提供的 3′-OH。请先放置引物。'}));const next=button('继续：合成新链',()=>go(3),'course-primary');next.disabled=!primer;actions.append(next);$('reactionBox').innerHTML='<strong>教学简化</strong><p>引物只画 3 个核苷酸以便观察，不代表真实引物长度。此处演示一个局部起点。</p>';return}
 if(!primer){controls.innerHTML='<h3>先建立起点</h3><p>还没有引物，DNA 聚合酶无法从零开始。</p>';controls.append(button('前往建立起点',()=>go(2),'course-primary'));return}
 if(added.length===5){controls.innerHTML='<h3>这一小段延伸完成了</h3><p>你连续加入了 5 个 DNA 核苷酸。粉色起始段仍是 RNA，引物替换与连接还没有完成。</p>';actions.append(button('重做这段练习',resetSynthesis),button('拉远看复制叉',()=>{go(1);setProgress(65)}),button('继续：完成与检查',()=>go(4),'course-primary'));$('reactionBox').innerHTML='<strong>同一规则不断重复</strong><p>前导链与每个冈崎片段的延伸都遵守 5′→3′。这里仅完成一个小片段，不是整条染色体。</p>';return}
 controls.innerHTML='<h3>模板当前是 '+template[3+added.length]+'，应该加入哪一种？</h3><div class="nucleotide-choices" id="nucleotideChoices"></div>';for(const b of ['A','T','G','C']){const choose=button('d'+b+'TP',()=>chooseBase(b));choose.dataset.choice=b;choose.disabled=!!candidate;$('nucleotideChoices').append(choose)}
 $('reactionBox').innerHTML=`<strong>DNA 聚合酶 · 简化总反应</strong><div class="synthesis-equation">DNAₙ–3′OH + <span id="incomingNucleotide">${candidate?'d'+candidate+'TP':'dNTP'}</span><br>→ DNAₙ₊₁–3′OH + PPᵢ</div><p>PPᵢ 是焦磷酸，含两个磷原子；它与前面 ATP 水解中的 Pᵢ 不同。省略电荷、质子与 Mg²⁺ 配位。</p>`;
 if(candidate){$('synthesisFeedback').textContent='互补配对正确。现在还只是候选核苷酸就位，尚未与新链形成共价连接。';const join=button('形成磷酸二酯键',joinBase,'course-primary');join.id='joinNucleotide';actions.append(join,button('重新选择',()=>{candidate=null;render()}));$('synthesisVisual').innerHTML=`<div class="bond-detail"><span>已有链的 3′-OH</span><b>＋</b><span>d${candidate}TP：糖–Pα–Pβ–Pγ</span><p>下一步：3′ 端与 α 磷酸形成骨架连接，β、γ 磷酸作为 PPᵢ 离开。</p></div>`}else $('synthesisFeedback').textContent='选择一个完整的脱氧核苷三磷酸（dNTP），不是只选择游离碱基。';actions.append(button('重做这段练习',resetSynthesis));
}
function chooseBase(b){if(candidate||added.length>=5||!primer)return;const target=template[3+added.length];if(complement[target]!==b){$('synthesisFeedback').textContent=`暂不加入：模板 ${target} 应与 ${complement[target]} 配对。请再选一次。这里的选择反馈不代表聚合酶校对已经发生。`;return}candidate=b;render()}
function joinBase(){if(!candidate||added.length>=5)return;const b=candidate;added.push(b);candidate=null;render();$('synthesisFeedback').textContent=`已加入 ${b}：形成一条新的磷酸二酯键并释放 PPᵢ。新链的 3′-OH 移到了刚加入的核苷酸上。`;$('synthesisVisual').innerHTML='<div class="bond-detail joined"><strong>新骨架连接已形成 · PPᵢ 已释放</strong><p>新链又延长了一个核苷酸，方向仍是 5′→3′。</p></div>'}
function resetSynthesis(){primer=false;added=[];candidate=null;go(2)}
const finishing=[['替换 RNA 引物','RNA 引物被移除，缺口由 DNA 补上。所用酶因生物类群而异；下图只表示处理结果。'],['连接骨架断口','DNA 连接酶封闭相邻 DNA 之间的骨架断口。补入核苷酸与封闭断口是不同的工作。'],['追踪亲代链','每个子代 DNA 都含一条亲代链和一条新合成链：这就是半保留复制。下图为结果概览，并非本练习已经复制完整条染色体。']];
function renderFinish(panel){panel.innerHTML+=`<div class="lesson-grid"><div class="sequence-surface"><div class="finish-tabs" id="finishTabs"></div><div id="daughterDiagram"></div></div><div class="lesson-copy"><h3>${finishing[finishStep][0]}</h3><p>${finishing[finishStep][1]}</p><details><summary>校对发生在哪里？</summary><p>许多复制型 DNA 聚合酶在延伸时可移除新链 3′ 端的错配核苷酸，再继续合成；并不是等整条 DNA 复制完才统一校对。本课“选错后重选”只用于练习配对，不是校对机制动画。</p></details><div class="course-actions" id="finishActions"></div></div></div>`;finishing.forEach((s,i)=>{let b=button((i+1)+' '+s[0],()=>{finishStep=i;render()});b.setAttribute('aria-pressed',i===finishStep);$('finishTabs').append(b)});if(finishStep<2){$('daughterDiagram').innerHTML=`<div class="finished-fragment"><span>亲代模板 3′</span><div class="parent-line">T A C G A T C G</div><span>5′</span></div><div class="finished-fragment"><span>新链 5′</span><div class="new-line">A T G C${finishStep===0?'<b class="nick">︱</b>':'—'}T A G C</div><span>3′</span></div><p class="diagram-note">${finishStep===0?'粉色 RNA 已替换为 DNA；中间断口被放大标记。':'断口封闭后，DNA 骨架连续。'} 图示为局部处理概念，不按真实比例。</p>`}else{$('daughterDiagram').innerHTML=`<div class="daughter-pair">${['甲','乙'].map((x,i)=>`<div><h4>子代 DNA ${x}</h4><div class="parent-line">${i?'5′　亲代链 B　3′':'3′　亲代链 A　5′'}</div><div class="new-line">${i?'3′　新合成链　5′':'5′　新合成链　3′'}</div></div>`).join('')}</div><p class="diagram-note">蓝色：亲代链；绿色：新合成链。</p>`}if(finishStep<2)$('finishActions').append(button('下一步',()=>{finishStep++;render()},'course-primary'));$('finishActions').append(button('用关闭连接酶实验验证',()=>{go(1);selectExperiment('ligase')}),button('回到核苷酸练习',()=>go(3)));}
document.querySelectorAll('[data-chapter]').forEach((b,i)=>b.onclick=()=>go(i));$('returnFork').onclick=()=>{go(1);setProgress(65)};go(0);
})();
